package com.oasis.library.web;
import com.oasis.library.model.*; import com.oasis.library.repo.*; import jakarta.servlet.http.HttpSession;
import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import java.time.LocalDate; import java.util.*;
@Controller public class LibraryController {
 private final BookRepository books; private final MemberRepository members; private final LoanRepository loans; private final ReservationRepository reservations; private final QueryRepository queries;
 public LibraryController(BookRepository b,MemberRepository m,LoanRepository l,ReservationRepository r,QueryRepository q){books=b;members=m;loans=l;reservations=r;queries=q;}
 @GetMapping("/") public String root(){return "redirect:/login";}
 @GetMapping("/login") public String login(){return "login";}
 @PostMapping("/login") public String doLogin(@RequestParam String email,@RequestParam String password,HttpSession s,RedirectAttributes ra){if(email.equalsIgnoreCase("admin@lumina.local")&&password.equals("Admin@123")){s.setAttribute("role","ADMIN");s.setAttribute("name","Library Admin");return "redirect:/dashboard";}if(email.equalsIgnoreCase("reader@lumina.local")&&password.equals("Reader@123")){s.setAttribute("role","MEMBER");s.setAttribute("name","Demo Reader");return "redirect:/dashboard";}ra.addFlashAttribute("error","Invalid demo credentials. Try one of the accounts below.");return "redirect:/login";}
 @GetMapping("/logout") public String logout(HttpSession s){s.invalidate();return "redirect:/login";}
 @GetMapping("/dashboard") public String dashboard(Model m,HttpSession s){m.addAttribute("bookCount",books.count());m.addAttribute("memberCount",members.count());m.addAttribute("issuedCount",loans.findByStatusOrderByDueDateAsc("ISSUED").size());m.addAttribute("overdueCount",loans.findByStatusOrderByDueDateAsc("ISSUED").stream().filter(x->x.getDueDate().isBefore(LocalDate.now())).count());m.addAttribute("recentBooks",books.findAll().stream().limit(5).toList());m.addAttribute("name",s.getAttribute("name"));return "dashboard";}
 @GetMapping("/books") public String bookList(@RequestParam(required=false) String q,@RequestParam(required=false) String category,Model m){List<Book> list=(q!=null&&!q.isBlank())?books.findByTitleContainingIgnoreCaseOrAuthorContainingIgnoreCaseOrIsbnContainingIgnoreCase(q,q,q):books.findAll();if(category!=null&&!category.isBlank())list=list.stream().filter(b->b.getCategory().equalsIgnoreCase(category)).toList();m.addAttribute("books",list);m.addAttribute("q",q==null?"":q);m.addAttribute("category",category==null?"":category);m.addAttribute("categories",books.findAll().stream().map(Book::getCategory).distinct().sorted().toList());return "books";}
 @GetMapping("/books/new") public String newBook(Model m){m.addAttribute("book",new Book());m.addAttribute("formTitle","Add a book");return "book-form";}
 @GetMapping("/books/{id}/edit") public String editBook(@PathVariable Long id,Model m){m.addAttribute("book",books.findById(id).orElseThrow());m.addAttribute("formTitle","Edit book");return "book-form";}
 @PostMapping("/books/save") public String saveBook(@ModelAttribute Book b,RedirectAttributes ra){if(b.getQuantity()<0)b.setQuantity(0);if(b.getId()==null)b.setAvailable(b.getQuantity());books.save(b);ra.addFlashAttribute("success","Book saved.");return "redirect:/books";}
 @PostMapping("/books/{id}/delete") public String deleteBook(@PathVariable Long id,RedirectAttributes ra){books.deleteById(id);ra.addFlashAttribute("success","Book removed.");return "redirect:/books";}
 @GetMapping("/members") public String memberList(Model m){m.addAttribute("members",members.findAll());return "members";}
 @PostMapping("/members/save") public String saveMember(@RequestParam String name,@RequestParam String email,@RequestParam(required=false) String phone,RedirectAttributes ra){members.save(new Member(name,email,phone,"MEMBER"));ra.addFlashAttribute("success","Member registered.");return "redirect:/members";}
 @GetMapping("/loans") public String loanList(Model m){m.addAttribute("loans",loans.findAll());m.addAttribute("books",books.findAll());m.addAttribute("members",members.findAll());return "loans";}
 @PostMapping("/loans/issue") public String issue(@RequestParam Long bookId,@RequestParam Long memberId,RedirectAttributes ra){Book b=books.findById(bookId).orElseThrow();Member u=members.findById(memberId).orElseThrow();if(b.getAvailable()<1){ra.addFlashAttribute("error","No copies available. Add a reservation instead.");return "redirect:/loans";}b.setAvailable(b.getAvailable()-1);books.save(b);loans.save(new Loan(b.getId(),u.getId(),b.getTitle(),u.getName(),LocalDate.now(),LocalDate.now().plusDays(14)));ra.addFlashAttribute("success","Book issued for 14 days.");return "redirect:/loans";}
 @PostMapping("/loans/{id}/return") public String returnBook(@PathVariable Long id,RedirectAttributes ra){Loan l=loans.findById(id).orElseThrow();if("ISSUED".equals(l.getStatus())){l.setStatus("RETURNED");l.setReturnDate(LocalDate.now());loans.save(l);Book b=books.findById(l.getBookId()).orElseThrow();b.setAvailable(b.getAvailable()+1);books.save(b);ra.addFlashAttribute("success","Book returned. Fine calculated: ₹"+l.getFine());}return "redirect:/loans";}
 @PostMapping("/loans/{id}/fine-paid") public String finePaid(@PathVariable Long id,RedirectAttributes ra){Loan l=loans.findById(id).orElseThrow();l.setFinePaid(true);loans.save(l);ra.addFlashAttribute("success","Fine marked as paid.");return "redirect:/loans";}
 @GetMapping("/reservations") public String reservationList(Model m){m.addAttribute("reservations",reservations.findAll());m.addAttribute("books",books.findAll());m.addAttribute("members",members.findAll());return "reservations";}
 @PostMapping("/reservations/save") public String reserve(@RequestParam Long bookId,@RequestParam Long memberId,RedirectAttributes ra){Book b=books.findById(bookId).orElseThrow();Member u=members.findById(memberId).orElseThrow();reservations.save(new Reservation(b.getId(),u.getId(),b.getTitle(),u.getName()));ra.addFlashAttribute("success","Reservation added to waiting list.");return "redirect:/reservations";}
 @GetMapping("/queries") public String queryList(Model m){m.addAttribute("queries",queries.findAll());return "queries";}
 @PostMapping("/queries/save") public String querySave(@RequestParam String name,@RequestParam String email,@RequestParam String message,RedirectAttributes ra){queries.save(new LibraryQuery(name,email,message));ra.addFlashAttribute("success","Message sent to library team.");return "redirect:/queries";}
 @PostMapping("/queries/{id}/resolve") public String resolve(@PathVariable Long id){LibraryQuery q=queries.findById(id).orElseThrow();q.setResolved(true);queries.save(q);return "redirect:/queries";}
}
